("rename","int rename(const char *old, const char *new);","Renames a file.","If a file with the new name exists it is replaced.","0 on success, nonzero on error.","remove",None),
("rewind","void rewind(FILE *stream);","Sets the file position to the start of a stream.","Equivalent to fseek(stream, 0L, SEEK_SET) followed by clearerr(stream).","Nothing.","fseek clearerr",None),
("scanf","int scanf(const char *format, ...);","Reads formatted input from stdin.","The format string holds conversion specifications that start with %, white space (which matches any amount of white space) and ordinary characters (which must match the input). Every argument after the format must be a pointer. See {scanf formats}.","The number of items assigned, or EOF if input ended before the first conversion.","fscanf sscanf gets","#include <stdio.h>\n\nint main(void)\n{\n    int a;\n    float b;\n    char name[20];\n    if (scanf(\"%d %f %19s\", &a, &b, name) == 3)\n        printf(\"%d %g %s\\n\", a, b, name);\n    return 0;\n}"),
("setbuf","void setbuf(FILE *stream, char *buf);","Sets the buffer of a stream.","buf must point to an array of BUFSIZ characters; with NULL the stream is unbuffered. Call it before any other operation on the stream.","Nothing.","setvbuf",None),
("setvbuf","int setvbuf(FILE *stream, char *buf, int mode, size_t size);","Sets the buffering mode and buffer of a stream.","mode is _IOFBF (full buffering), _IOLBF (line buffering) or _IONBF (no buffering). If buf is NULL the library allocates a buffer of the given size. Call it before any other operation on the stream.","0 on success, nonzero otherwise.","setbuf fflush",None),
("sprintf","int sprintf(char *s, const char *format, ...);","Writes formatted output to a string.","Works like printf but stores the result in s and ends it with a null character. The array must be large enough; sprintf cannot check.","The number of characters stored, not counting the null character.","printf vsprintf sscanf",None),
("sscanf","int sscanf(const char *s, const char *format, ...);","Reads formatted input from a string.","Works like scanf but takes its input from s. See {scanf formats}.","The number of items assigned, or EOF if the string ended before the first conversion.","scanf fscanf sprintf",None),
