("tmpnam","char *tmpnam(char *s);","Generates a file name that is not in use.","If s is NULL a static buffer is used, otherwise s must point to an array of at least L_tmpnam characters. At most TMP_MAX different names can be produced.","The name, or NULL on failure.","tmpfile",None),
("ungetc","int ungetc(int c, FILE *stream);","Pushes a character back onto an input stream.","One character of pushback is guaranteed. EOF cannot be pushed back. A successful fseek, fsetpos or rewind discards the pushed-back character.","c, or EOF on failure.","fgetc fseek",None),
("vfprintf","int vfprintf(FILE *stream, const char *format, va_list arg);","Writes formatted output to a stream using an argument list.","Like fprintf, but the variable arguments are passed as a va_list. The function does not call va_end.","The number of characters written, or a negative value on error.","fprintf vprintf vsprintf va_start",None),
("vprintf","int vprintf(const char *format, va_list arg);","Writes formatted output to stdout using an argument list.","Like printf with a va_list. The function does not call va_end.","The number of characters written, or a negative value on error.","printf vfprintf va_start","#include <stdarg.h>\n#include <stdio.h>\n\nvoid log_msg(const char *fmt, ...)\n{\n    va_list ap;\n    va_start(ap, fmt);\n    vprintf(fmt, ap);\n    va_end(ap);\n}\n\nint main(void)\n{\n    log_msg(\"%s=%d\\n\", \"x\", 5);\n    return 0;\n}"),
